import{_ as t,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 5 课 问得最多的 10 个问题","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第5课 问得最多的10个问题.md","filePath":"easy/第5课 问得最多的10个问题.md"}'),n={name:"easy/第5课 问得最多的10个问题.md"};function s(h,a,l,i,_,u){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="第-5-课-问得最多的-10-个问题" tabindex="-1">第 5 课 问得最多的 10 个问题 <a class="header-anchor" href="#第-5-课-问得最多的-10-个问题" aria-label="Permalink to &quot;第 5 课 问得最多的 10 个问题&quot;">​</a></h1><blockquote><p>都是新手朋友常问的，先替你问了，放心看。</p></blockquote><h2 id="_1️⃣-它会不会把我的文件弄坏" tabindex="-1">1️⃣ 它会不会把我的文件弄坏？ <a class="header-anchor" href="#_1️⃣-它会不会把我的文件弄坏" aria-label="Permalink to &quot;1️⃣ 它会不会把我的文件弄坏？&quot;">​</a></h2><p><strong>一般不会，但我要守规矩。</strong> 危险操作（删文件、覆盖、改一堆东西）之前，我会先问你、先给你看计划。你只要记住一条：<strong>它动手前，你点头。</strong> 另外，我推荐你重要文件先备份，这是好习惯，跟用不用 AI 没关系。</p><h2 id="_2️⃣-我完全不懂技术-能用吗" tabindex="-1">2️⃣ 我完全不懂技术，能用吗？ <a class="header-anchor" href="#_2️⃣-我完全不懂技术-能用吗" aria-label="Permalink to &quot;2️⃣ 我完全不懂技术，能用吗？&quot;">​</a></h2><p><strong>能，而且这本易懂版就是给你写的。</strong> 你不需要懂代码，只需要会&quot;点菜&quot;（第 2 课那个公式）。剩下的，我来。</p><h2 id="_3️⃣-它说的话我能信吗" tabindex="-1">3️⃣ 它说的话我能信吗？ <a class="header-anchor" href="#_3️⃣-它说的话我能信吗" aria-label="Permalink to &quot;3️⃣ 它说的话我能信吗？&quot;">​</a></h2><p><strong>大部分能信，但别全信。</strong> 尤其是数字、日期、别人的观点——重要信息请你核对一下。记住：<strong>它像同事，同事也会犯错，重要的事要复核。</strong></p><h2 id="_4️⃣-它能记住我吗-还是每次都要重说" tabindex="-1">4️⃣ 它能记住我吗？还是每次都要重说？ <a class="header-anchor" href="#_4️⃣-它能记住我吗-还是每次都要重说" aria-label="Permalink to &quot;4️⃣ 它能记住我吗？还是每次都要重说？&quot;">​</a></h2><p><strong>能记住。</strong> 它有小本本（记忆系统），你说&quot;记住：我喜欢 XX&quot;，它下次就记得。也可以随时说&quot;忘掉 XX&quot;。</p><h2 id="_5️⃣-它会不会把我的隐私泄露出去" tabindex="-1">5️⃣ 它会不会把我的隐私泄露出去？ <a class="header-anchor" href="#_5️⃣-它会不会把我的隐私泄露出去" aria-label="Permalink to &quot;5️⃣ 它会不会把我的隐私泄露出去？&quot;">​</a></h2><p><strong>它是你的同事，不是广播电台。</strong> 但注意：① 别把密码、验证码发给它；② 敏感文件注意存放位置；③ 它记的小本本是文件，你自己能看到、能删。</p><h2 id="_6️⃣-一次能让我做很多事吗" tabindex="-1">6️⃣ 一次能让我做很多事吗？ <a class="header-anchor" href="#_6️⃣-一次能让我做很多事吗" aria-label="Permalink to &quot;6️⃣ 一次能让我做很多事吗？&quot;">​</a></h2><p><strong>最好一件一件来。</strong> 像点菜：一次点十个菜，容易乱；一次一道，道道做好。任务大可以让我&quot;拆成步骤&quot;，一步一步来。</p><h2 id="_7️⃣-它帮我写的东西-版权算谁的" tabindex="-1">7️⃣ 它帮我写的东西，版权算谁的？ <a class="header-anchor" href="#_7️⃣-它帮我写的东西-版权算谁的" aria-label="Permalink to &quot;7️⃣ 它帮我写的东西，版权算谁的？&quot;">​</a></h2><p><strong>算你的。</strong> 它是工具，你是主人。你把它写的东西拿去用、去改、去发表，都没问题。（正式场合建议你过目修改一下，更放心。）</p><h2 id="_8️⃣-用它能省多少时间" tabindex="-1">8️⃣ 用它能省多少时间？ <a class="header-anchor" href="#_8️⃣-用它能省多少时间" aria-label="Permalink to &quot;8️⃣ 用它能省多少时间？&quot;">​</a></h2><p><strong>看你会不会用。</strong> 用得好：写东西快 3～5 倍，找东西快 10 倍，重复活几乎全包。用不好（光聊天不干活）：省 0 分钟。<strong>关键是让它&quot;干活&quot;，不是让它&quot;聊天&quot;。</strong></p><h2 id="_9️⃣-它和-chatgpt-有什么区别" tabindex="-1">9️⃣ 它和 ChatGPT 有什么区别？ <a class="header-anchor" href="#_9️⃣-它和-chatgpt-有什么区别" aria-label="Permalink to &quot;9️⃣ 它和 ChatGPT 有什么区别？&quot;">​</a></h2><p><strong>形态不同。</strong> 网页聊天框只能聊；我住在你电脑里，能<strong>直接碰你的文件、跑你的程序、干完活给你成品</strong>。好比：一个是电话咨询，一个是上门干活的同事。</p><h2 id="🔟-用出问题了找谁" tabindex="-1">🔟 用出问题了找谁？ <a class="header-anchor" href="#🔟-用出问题了找谁" aria-label="Permalink to &quot;🔟 用出问题了找谁？&quot;">​</a></h2><p><strong>找我！</strong> 直接说&quot;刚才那个不对&quot;，我会修正。如果是我能力之外的，我会告诉你&quot;这个我搞不定&quot;，并尽量告诉你去哪找答案。<strong>我的失败，也应该是透明的。</strong></p><hr><h2 id="还有问题" tabindex="-1">还有问题？ <a class="header-anchor" href="#还有问题" aria-label="Permalink to &quot;还有问题？&quot;">​</a></h2><p>没关系，直接问它。<strong>&quot;问&quot;就是最好的学习方式</strong>——它回答得不好，你就换个问法，多试两次，你会越来越顺手。</p><p>👉 学会问了，再拿一张 <a href="./话术小抄：复制就能用.html">话术小抄</a> 走天下。</p>',26)])])}const c=t(n,[["render",s]]);export{q as __pageData,c as default};
